package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import java.nio.charset.StandardCharsets;
final class ConnectorActionsAcceptance {
    static final String API="/api/openservice/connector-actions";
    static Map<String,Object> spec(String alias,int revision,String method){return map("name","Reviewed external service","alias",alias,"method",method,"path","/write","inputs",List.of(CatalogueQuestionsAcceptance.question("title","string",true,List.of())),"active",true,"revision",revision);}
    static Map<String,Object> result(java.net.http.HttpResponse<byte[]> response,int expected){return CatalogueQuestionsAcceptance.result(response,expected);}
    static String create(WorkflowSupport h,String alias)throws Exception{return result(h.json("POST",API,spec(alias,0,"POST"),auth("admin")),201).get("action_id").toString();}
    static Map<String,Object> preview(WorkflowSupport h,String id,String key)throws Exception{return object(result(h.json("POST",API+"/"+id+"/run",map("operation","preview","values",map("title","Exact reviewed input <script>"),"key",key),auth("admin")),200).get("preview"));}
    static Map<String,Object> queueInput(Map<String,Object> preview){return map("operation","queue","values",preview.get("values"),"key",preview.get("key"),"state",preview.get("state"),"preview_token",preview.get("preview_token"),"confirm",true);}
    static String queue(WorkflowSupport h,String id,Map<String,Object> preview)throws Exception{return result(h.json("POST",API+"/"+id+"/run",queueInput(preview),auth("admin")),201).get("job_id").toString();}
    static Map<String,Object> job(WorkflowSupport h,String id)throws Exception{return result(h.get("/api/openservice/operations/jobs/"+id,auth("admin")),200);}
    static final class Endpoint implements AutoCloseable {
        final RecordQuestionsAcceptance.Provider provider;final AtomicInteger calls=new AtomicInteger(),status=new AtomicInteger(201);final AtomicReference<String> method=new AtomicReference<>(),body=new AtomicReference<>(),key=new AtomicReference<>(),mode=new AtomicReference<>("ok");
        Endpoint(WorkflowSupport h)throws Exception{this(h.store,h.environment);}
        Endpoint(Store store,org.springframework.core.env.Environment env)throws Exception{
            provider=new RecordQuestionsAcceptance.Provider(store,env);provider.settings.put("CONNECTOR_WRITES_ENABLED","true");provider.server.createContext("/write",exchange->{calls.incrementAndGet();method.set(exchange.getRequestMethod());body.set(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));key.set(exchange.getRequestHeaders().getFirst("Idempotency-Key"));provider.authorization.set(exchange.getRequestHeaders().getFirst("Authorization"));if(mode.get().equals("close")){exchange.close();return;}byte[] bytes=(mode.get().equals("large")?"x".repeat(1024*1024+1):"private external receipt").getBytes(StandardCharsets.UTF_8);if(status.get()==302)exchange.getResponseHeaders().add("Location",provider.origin()+"/must-not-follow");try{exchange.sendResponseHeaders(status.get(),bytes.length);exchange.getResponseBody().write(bytes);}catch(java.io.IOException ignored){}finally{exchange.close();}});
            provider.server.createContext("/must-not-follow",exchange->{calls.addAndGet(100);exchange.sendResponseHeaders(200,-1);exchange.close();});
        }
        public void close()throws Exception{provider.close();}
    }
    static void run(WorkflowSupport h)throws Exception{
        h.account("ActionReader","reader");h.account("ActionOther","admin");assertEquals(200,h.get(API,auth("admin")).statusCode());assertEquals(403,h.get(API,auth("ActionReader")).statusCode());assertEquals(401,h.get(API,null).statusCode());assertEquals(400,h.get(API+"?unexpected=x",auth("admin")).statusCode());assertEquals(405,h.json("DELETE",API,map(),auth("admin")).statusCode());
        try(var endpoint=new Endpoint(h)){
            String id=create(h,endpoint.provider.alias),path=API+"/"+id,run=path+"/run";assertEquals(200,h.get(path,auth("admin")).statusCode());assertEquals(200,h.get(run,auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());assertEquals(200,h.get(API+"/new",auth("admin")).statusCode());assertEquals(1,objects(parsed(h.get(API,auth("admin"))).get("result")).size());
            for(var bad:List.of(map(),spec("missing",0,"POST"),spec(endpoint.provider.alias,1,"POST"),spec(endpoint.provider.alias,0,"GET"))){assertTrue(Set.of(400,404).contains(h.json("POST",API,bad,auth("admin")).statusCode()));}
            for(var field:List.of(Map.entry("revision",(Object)"0"),Map.entry("revision",(Object)(-1)),Map.entry("active",(Object)"true"),Map.entry("path",(Object)"/bad path"),Map.entry("path",(Object)"//outside"),Map.entry("inputs",(Object)List.of(map())))){var bad=spec(endpoint.provider.alias,0,"POST");bad.put(field.getKey(),field.getValue());assertEquals(400,h.json("POST",API,bad,auth("admin")).statusCode());}
            var disabled=spec(endpoint.provider.alias,1,"POST");disabled.put("active",false);assertEquals(200,h.json("PUT",path,disabled,auth("admin")).statusCode());assertEquals(409,h.json("PUT",path,disabled,auth("admin")).statusCode());assertEquals(400,h.json("POST",run,map("operation","preview","values",map("title","x"),"key",id()),auth("admin")).statusCode());assertEquals(200,h.json("PUT",path,spec(endpoint.provider.alias,2,"POST"),auth("admin")).statusCode());endpoint.provider.settings.put("CONNECTOR_WRITES_ENABLED","false");assertEquals(400,h.json("POST",run,map("operation","preview","values",map("title","x"),"key",id()),auth("admin")).statusCode());endpoint.provider.settings.put("CONNECTOR_WRITES_ENABLED","true");
            for(var bad:List.of(map("operation","unknown"),map("operation","preview","values",map(),"key",id()),map("operation","preview","values",map("title","x")),map("operation","preview","values",map("unknown","x"),"key",id()))){assertEquals(400,h.json("POST",run,bad,auth("admin")).statusCode());}
            var preview=preview(h,id,id());assertEquals(endpoint.provider.origin()+"/write",preview.get("destination"));assertEquals("{\"title\":\"Exact reviewed input <script>\"}",preview.get("content"));assertEquals(0,endpoint.calls.get());
            for(var change:List.of(Map.entry("confirm",(Object)false),Map.entry("preview_token",(Object)"forged"),Map.entry("action_id",(Object)id))){var bad=queueInput(preview);bad.put(change.getKey(),change.getValue());assertEquals(400,h.json("POST",run,bad,auth("admin")).statusCode());}
            var expired=queueInput(preview);expired.put("preview_token",CatalogueAssistAcceptance.expired(h.store,preview.get("preview_token").toString()));assertEquals(409,h.json("POST",run,expired,auth("admin")).statusCode());var changed=queueInput(preview);changed.put("values",map("title","changed"));assertEquals(409,h.json("POST",run,changed,auth("admin")).statusCode());assertEquals(409,h.json("POST",run,queueInput(preview),auth("ActionOther")).statusCode());var extra=queueInput(preview);extra.put("extra",true);assertEquals(400,h.json("POST",run,extra,auth("admin")).statusCode());
            var direct=new LinkedHashMap<>(queueInput(preview));direct.remove("operation");direct.put("action_id",id);assertEquals(400,h.json("POST","/api/openservice/operations/jobs",map("kind","connector.write","key","different","payload",direct),auth("admin")).statusCode());
            String job=queue(h,id,preview);assertEquals(job,queue(h,id,preview));assertEquals(0,endpoint.calls.get());new Store(h.environment);assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(1,endpoint.calls.get());assertEquals("POST",endpoint.method.get());assertEquals(preview.get("content"),endpoint.body.get());assertEquals(job,endpoint.key.get());assertEquals("Bearer synthetic-question-token",endpoint.provider.authorization.get());var receipt=job(h,job);assertEquals("succeeded",receipt.get("state"));assertEquals(201,object(receipt.get("receipt")).get("http_status"));assertTrue(Boolean.TRUE.equals(object(receipt.get("receipt")).get("acknowledged")));assertFalse(JSON.writeValueAsString(receipt).contains("private external receipt"));assertFalse(JSON.writeValueAsString(receipt).contains("synthetic-question-token"));assertEquals(job,queue(h,id,preview));assertFalse(new WorkWorker(h.store).runOne(System.currentTimeMillis()+2000));assertEquals(1,endpoint.calls.get());
            int revision=3;for(String method:List.of("PUT","PATCH","DELETE")){assertEquals(200,h.json("PUT",path,spec(endpoint.provider.alias,revision++,method),auth("admin")).statusCode());String next=queue(h,id,preview(h,id,id()));assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+3000));assertEquals(method,endpoint.method.get());assertEquals("succeeded",job(h,next).get("state"));}
            assertEquals(4,endpoint.calls.get());String reconcile="/api/openservice/operations/jobs/"+job+"/reconcile";assertNull(result(h.get(reconcile,auth("admin")),200).get("resolution"));for(var bad:List.of(map(),map("decision","unknown","note","Unverified"),map("decision","applied","note","")))assertEquals(400,h.json("POST",reconcile,bad,auth("admin")).statusCode());var verified=map("decision","applied","note","External receipt ABC confirms the requested work");assertEquals(200,h.json("POST",reconcile,verified,auth("admin")).statusCode());assertEquals(200,h.json("POST",reconcile,verified,auth("admin")).statusCode());assertEquals(409,h.json("POST",reconcile,map("decision","not_applied","note","Changed"),auth("admin")).statusCode());assertEquals(409,h.json("POST",reconcile,map("decision","applied","note","Changed"),auth("admin")).statusCode());assertEquals(403,h.get(reconcile,auth("ActionReader")).statusCode());assertEquals(404,h.get(reconcile.replace(job,id()),auth("admin")).statusCode());
            String waiting=queue(h,id,preview(h,id,id()));assertEquals(200,h.json("POST","/api/openservice/operations/jobs/"+waiting,map("operation","retry"),auth("admin")).statusCode());assertEquals(400,h.json("POST",reconcile.replace(job,waiting),verified,auth("admin")).statusCode());assertEquals(200,h.json("POST","/api/openservice/operations/jobs/"+waiting,map("operation","cancel"),auth("admin")).statusCode());
            assertEquals(403,h.form("/admin/connector-actions/"+id+"/run",map("operation","preview"),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/connector-actions/"+id+"/run",map("operation","queue","confirm","false"),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/connector-actions/"+id,map("active","invalid","revision",revision),auth("admin")).statusCode());try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);db.update("UPDATE os_work SET created_at=0 WHERE job_id=?",job);WorkJobs.control(db,actor,"all","cleanup");assertEquals(0,db.count("SELECT COUNT(*) FROM os_connector_resolution WHERE job_id=?",job));db.connection.commit();}
        }
    }
    static void boundaries(WorkflowSupport h)throws Exception{
        try(var endpoint=new Endpoint(h)){
            String id=create(h,endpoint.provider.alias),run=API+"/"+id+"/run";long now=System.currentTimeMillis()+60000;
            for(int status:List.of(400,503,302)){endpoint.status.set(status);String job=queue(h,id,preview(h,id,id()));new WorkWorker(h.store).runOne(now);var detail=job(h,job);assertEquals("failed",detail.get("state"));assertEquals(status,object(detail.get("receipt")).get("http_status"));assertEquals(false,object(detail.get("receipt")).get("acknowledged"));assertEquals(400,h.json("POST","/api/openservice/operations/jobs/"+job,map("operation","retry"),auth("admin")).statusCode());assertFalse(new WorkWorker(h.store).runOne(now+1000000));}
            endpoint.status.set(201);for(String mode:List.of("large","close")){endpoint.mode.set(mode);String job=queue(h,id,preview(h,id,id()));new WorkWorker(h.store).runOne(now);assertEquals("failed",job(h,job).get("state"));assertEquals("RECONCILIATION_REQUIRED",job(h,job).get("error"));assertFalse(new WorkWorker(h.store).runOne(now+1000000));}assertEquals(5,endpoint.calls.get());endpoint.mode.set("ok");
            String reclaimed=queue(h,id,preview(h,id,id()));Map<String,Object> old;try(var db=h.store.open()){old=WorkJobs.claim(db,now);db.connection.commit();}assertEquals(reclaimed,old.get("job_id"));new Store(h.environment);new WorkWorker(h.store).runOne(now+120001);new WorkWorker(h.store).runClaimed(old,now+120002);assertEquals("failed",job(h,reclaimed).get("state"));assertEquals(5,endpoint.calls.get());assertEquals(400,h.json("POST","/api/openservice/operations/jobs/"+reclaimed,map("operation","retry"),auth("admin")).statusCode());
            var reviewed=preview(h,id,id());String pending=queue(h,id,reviewed);try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Connectors.save(h.store,db,actor,map("alias",endpoint.provider.alias,"origin",endpoint.provider.origin(),"token","rotated-token"));db.connection.commit();}new WorkWorker(h.store).runOne(now);assertEquals("failed",job(h,pending).get("state"));assertEquals(5,endpoint.calls.get());assertEquals(409,h.json("POST",run,queueInput(previewWithNewKey(reviewed)),auth("admin")).statusCode());
            endpoint.provider.settings.put("CONNECTOR_ALLOWED_ORIGINS","");assertEquals(400,h.json("POST",run,map("operation","preview","values",map("title","x"),"key",id()),auth("admin")).statusCode());endpoint.provider.settings.put("CONNECTOR_ALLOWED_ORIGINS",endpoint.provider.origin());
            var interrupted=preview(h,id,id());var payload=queueInput(interrupted);payload.remove("operation");payload.put("action_id",id);try(var db=h.store.open()){PlatformFoundationTest.bind(db);Thread.currentThread().interrupt();try{assertThrows(Failure.class,()->ConnectorWrites.execute(h.store,db,map("attempts",1,"job_id",id()),payload));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
            var body=ConnectorWrites.body("only once");var first=new Subscriber();body.subscribe(first);assertTrue(first.done.await(5,java.util.concurrent.TimeUnit.SECONDS));assertNull(first.error.get());assertEquals("only once",first.bytes.toString(StandardCharsets.UTF_8));var second=new Subscriber();body.subscribe(second);assertTrue(second.done.await(5,java.util.concurrent.TimeUnit.SECONDS));assertNotNull(second.error.get());assertEquals(0,second.bytes.size());
            String notification=WorkSearchAcceptance.seed(h.store,"Not external");assertEquals(400,h.get("/api/openservice/operations/jobs/"+notification+"/reconcile",auth("admin")).statusCode());assertEquals(200,h.json("POST","/api/openservice/operations/jobs/"+notification,map("operation","cancel"),auth("admin")).statusCode());
            var many=spec(endpoint.provider.alias,1,"POST");var fields=new ArrayList<Map<String,Object>>();var values=map();for(int n=0;n<5;n++){fields.add(CatalogueQuestionsAcceptance.question("field"+n,"string",true,List.of()));values.put("field"+n,"x".repeat(2000));}many.put("inputs",fields);assertEquals(200,h.json("PUT",API+"/"+id,many,auth("admin")).statusCode());assertEquals(400,h.json("POST",run,map("operation","preview","values",values,"key",id()),auth("admin")).statusCode());
            try(var db=h.store.open()){for(int n=1;n<200;n++)db.update("INSERT INTO os_connector_action(action_id,name,alias,method,path,inputs,active,revision) VALUES(?,?,?,?,?,?,?,?)",id(),"Capacity fixture",endpoint.provider.alias,"POST","/write","[]",1,1);db.connection.commit();}assertEquals(400,h.json("POST",API,spec(endpoint.provider.alias,0,"POST"),auth("admin")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_connector_action WHERE name=? AND alias=?","Capacity fixture",endpoint.provider.alias);db.connection.commit();}
        }
    }
    static Map<String,Object> previewWithNewKey(Map<String,Object> before){var changed=new LinkedHashMap<>(before);changed.put("key",id());return changed;}
    static final class Subscriber implements java.util.concurrent.Flow.Subscriber<java.nio.ByteBuffer>{
        final java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();final AtomicReference<Throwable> error=new AtomicReference<>();final java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);
        public void onSubscribe(java.util.concurrent.Flow.Subscription subscription){subscription.request(Long.MAX_VALUE);}public void onNext(java.nio.ByteBuffer value){byte[] part=new byte[value.remaining()];value.get(part);bytes.writeBytes(part);}public void onError(Throwable value){error.set(value);done.countDown();}public void onComplete(){done.countDown();}
    }
}
